INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('0a10d0ad-bb7b-5913-837d-a24b3165bd9b'::uuid, '8fe23c1a-fbd8-510a-8223-cfce9e8005d0'::uuid, 'Anytime Fitness', 'تم توفير خدمات تنظيف احترافية في نادي "Anytime Fitness"، شملت التنظيف الكامل لغرف التدريب، والمعدات الرياضية، وغرف تغيير الملابس، ودورات المياه، ومناطق الاستقبال، والنوافذ، والأرضيات. وقد نُفذت هذه الخدمات باستخدام معدات ومنتجات مناسبة، مع الالتزام بمعايير النظافة والسلامة والجودة، لضمان بيئة نظيفة وصحية ومريحة للأعضاء والموظفين.', '["https://lechantier.ma/uploads/media/debe2fdcc5fb.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/debe2fdcc5fb.webp', 'Fès', (SELECT id FROM public.internal_categories WHERE code = '8.6.1' LIMIT 1));
