INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('2cabc125-9da4-5bf8-940c-f1b06f7a006a'::uuid, 'e3da0388-5676-5381-ac65-f9453a82ea47'::uuid, 'entretien des espaces vert', 'nous mettons notre savoir-faire au service de vos espaces verts. Que vous soyez une entreprise, une collectivité ou un particulier, nous vous proposons des prestations de jardinage sur mesure, réalisées avec professionnalisme, ponctualité et respect de l’environnement', '["https://lechantier.ma/uploads/media/01c8be238e1a.webp", "https://lechantier.ma/uploads/media/804e7f917ece.webp", "https://lechantier.ma/uploads/media/6de7736fdf1c.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/01c8be238e1a.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '8.6.1' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('d404433d-780d-557f-8331-715eb2c99dd3'::uuid, 'e3da0388-5676-5381-ac65-f9453a82ea47'::uuid, 'cristallisation du marbre', 'La cristallisation du marbre est un procédé de traitement et de rénovation de ce type de pierre naturelle qui permet de redonner éclat, brillance et protection à la surface du marbre. Qu’est-ce que la cristallisation du marbre ? C’est un traitement chimique et mécanique combiné qui agit sur la surface du marbre. Il consiste à appliquer un produit', '["https://lechantier.ma/uploads/media/03e68b660521.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/03e68b660521.webp', 'Casablanca', (SELECT id FROM public.internal_categories WHERE code = '8.6.1' LIMIT 1));
