INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('71fdf0e4-5d14-5874-809b-b4b80ec200f7'::uuid, '5d4d9eb6-ce41-5910-93d7-f65fb7589911'::uuid, 'Taille-haie Thermique Professionnel', 'Taillez vos haies, buissons et arbustes avec efficacité grâce à ce taille-haie thermique professionnel. Équipé d''un lamier double action de 60 cm, il assure une coupe nette et rapide, venant à bout des branches jusqu''à 2-3 cm de diamètre. Sa conception équilibrée et son système anti-vibration offrent un grand confort d''utilisation, même pour les travaux prolongés dans le jardin. Fonctionne au mélange 2 temps.', '["https://lechantier.ma/uploads/media/ed6ce67e61d4.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/ed6ce67e61d4.webp', 'Salé', (SELECT id FROM public.internal_categories WHERE code = '3.5.2' LIMIT 1));
INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('a8a71260-6fa6-5547-9a06-2f72eb46e176'::uuid, '5d4d9eb6-ce41-5910-93d7-f65fb7589911'::uuid, 'Scie d’élagage sur perche MULTI-STAR – OZM3', 'La scie d’élagage sur perche MULTI-STAR OZM3 est un outil de jardinage pratique et efficace conçu pour la taille des branches en hauteur sans utiliser d’échelle. Grâce à son système MULTI-STAR, elle peut être fixée facilement sur une perche compatible, offrant une excellente portée et un confort d’utilisation optimal.', '[]'::jsonb, NULL, 'Salé', (SELECT id FROM public.internal_categories WHERE code = '3.5.2' LIMIT 1));
