INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('9504eecb-c13c-5ec0-88a6-8b9348818927'::uuid, 'b170c55a-e3b7-50b9-81e7-27c4de5e3ae6'::uuid, 'Centre D''Appel - Majorel', 'Dans le cadre de la remise en état post-chantier, notre intervention comprend les opérations suivantes : Dépoussiérage de la moquette avec aspiration en profondeur pour éliminer résidus, poussières fines et traces de chantier. Nettoyage des vitres intérieures et extérieures, y compris encadrements, pour une transparence parfaite...', '["https://lechantier.ma/uploads/media/9592a8e3bc82.webp", "https://lechantier.ma/uploads/media/10f7954d2a72.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/9592a8e3bc82.webp', 'Témara', (SELECT id FROM public.internal_categories WHERE code = '8.6.1' LIMIT 1));
