INSERT INTO public.realisations (id, user_id, title, description, images, cover, city, internal_category_id) VALUES ('aea9f6b2-a850-5fed-8133-c9761bb8508f'::uuid, '76174a1d-f3a4-5344-a117-ce0b385a04b7'::uuid, 'Plafond BA13 decorative', 'Réalisation d’un plafond en placo pour le salon d’une maison à Tanger. Structure métallique bien fixée, plaques de plâtre posées avec précision, intégration de spots LED. Un plafond moderne et raffiné qui apporte élégance, luminosité et confort à l’espace de vie', '["https://lechantier.ma/uploads/media/c6d863d64d47.webp", "https://lechantier.ma/uploads/media/c2a873cd0d94.webp", "https://lechantier.ma/uploads/media/1100cc404306.webp"]'::jsonb, 'https://lechantier.ma/uploads/media/c6d863d64d47.webp', 'Tanger', (SELECT id FROM public.internal_categories WHERE code = '3.2.7' LIMIT 1));
